import type { HierarchyNode } from '../hierarchy/groupHierarchy';
import type { RefactorGroup, RefactorRange, SourceRange } from '../models/refactorGroup';
import { isSafeRelativePath } from '../storage/serialization';
import { isNonEmptyRange } from '../utils/ranges';
import { isGeneratedPath } from '../utils/storagePaths';
import { parseGroupPath, validateGroupName, validateGroupNameCharacters } from '../validation/groupNames';

export const FUNCTION_DRAFT_DISCLAIMER = [
  '// Refactoring draft generated by Refactor Marker.',
  '// This file is not guaranteed to be valid or compilable TypeScript.',
  '// Imports, parameters, return values, async behavior, and external dependencies are not analyzed.',
].join('\n');

function requireExportableName(name: string): void {
  const problem = validateGroupName(name) ?? validateGroupNameCharacters(name);
  if (problem !== undefined) {
    throw new Error(`Cannot export the stored group name "${name}": ${problem}`);
  }
}

/** Filename conversion applies only to export; unsafe legacy names are never rewritten. */
export function exportFileName(name: string): string {
  requireExportableName(name);
  const fileStem = parseGroupPath(name)[0].toLowerCase().replace(/ /gu, '_');
  if (/^(?:con|prn|aux|nul|com[1-9]|lpt[1-9])$/iu.test(fileStem)) {
    throw new Error(`The top-level group name "${parseGroupPath(name)[0]}" is a reserved filename. Rename it before exporting.`);
  }
  return `${fileStem}.ts`;
}

/** Uppercase word initials while retaining existing camel-case or acronym spelling. */
export function functionName(segment: string): string {
  if (segment.includes('/')) {
    throw new Error('Function names must be derived from a single hierarchy segment.');
  }
  requireExportableName(segment);
  const result = segment.split(/[ _-]+/u).filter(Boolean)
    .map(word => {
      const [initial, ...rest] = Array.from(word);
      return initial.toUpperCase() + rest.join('');
    }).join('');
  // Separator-only segments are valid stored names and still need a draft function.
  return result || '_';
}

/** Return a user-facing conflict instead of choosing one unrelated hierarchy to overwrite. */
export function findExportFileNameCollision(groups: readonly RefactorGroup[], selectedName: string): string | undefined {
  const selectedTop = parseGroupPath(selectedName)[0];
  const target = exportFileName(selectedName).toLowerCase();
  const seen = new Set<string>();
  for (const group of groups) {
    const candidateTop = parseGroupPath(group.name)[0];
    if (candidateTop === selectedTop || seen.has(candidateTop)) {
      continue;
    }
    seen.add(candidateTop);
    let candidate: string;
    try {
      candidate = exportFileName(candidateTop);
    } catch {
      // A legacy name that cannot be exported cannot own this generated filename.
      continue;
    }
    if (candidate.toLowerCase() === target) {
      return `Cannot export: top-level groups "${selectedTop}" and "${candidateTop}" both map to "${target}". Rename one group before exporting.`;
    }
  }
  return undefined;
}

/** Reject coordinates that a document API might otherwise silently clamp. */
export function validateExportRange(range: SourceRange): void {
  if (![range.startLine, range.startCharacter, range.endLine, range.endCharacter]
    .every(coordinate => Number.isSafeInteger(coordinate) && coordinate >= 0)
    || !isNonEmptyRange(range)) {
    throw new Error('Cannot export an invalid or empty stored source range.');
  }
}

function indentSource(text: string, indent: string): string {
  // Adding whitespace after a newline can change template or continued string literals.
  // Indent the first line only, preserving every subsequent source byte verbatim.
  return indent + text;
}

export type ReadRangeText = (range: RefactorRange) => Promise<string>;

/** Render sequentially so reads and output follow range insertion order exactly. */
export async function renderFunctionDraft(root: HierarchyNode, readRange: ReadRangeText): Promise<string> {
  async function renderNode(node: HierarchyNode, depth: number): Promise<string> {
    requireExportableName(node.path);
    const indent = '  '.repeat(depth);
    const bodyIndent = `${indent}  `;
    const body: string[] = [];
    for (const group of node.groups) {
      requireExportableName(group.name);
      for (const range of group.ranges) {
        if (!isSafeRelativePath(range.filePath) || isGeneratedPath(range.filePath) || /[\u2028\u2029]/u.test(range.filePath)) {
          throw new Error(`Cannot export an unsafe source path: "${range.filePath}".`);
        }
        validateExportRange(range);
        const text = await readRange(range);
        if (text.length === 0) {
          throw new Error(`Cannot read text for the stored source range in "${range.filePath}".`);
        }
        body.push(`${bodyIndent}// ${range.filePath}\n${indentSource(text, bodyIndent)}`);
      }
    }
    for (const child of node.children) {
      body.push(await renderNode(child, depth + 1));
    }
    const content = body.length > 0 ? `\n${body.join('\n\n')}\n` : '\n';
    return `${indent}function ${functionName(node.segment.trim())}() {${content}${indent}}`;
  }
  return `${FUNCTION_DRAFT_DISCLAIMER}\n\n${await renderNode(root, 0)}\n`;
}
